// Export searoute-js results to CSV.
//
//   node test.js             -> routes_summary.csv + route_waypoints.csv
//   node test.js --network   -> also searoute_network.csv (the whole shipping-lane network)
//
// Coordinates are [longitude, latitude] everywhere, as in GeoJSON.

const fs = require('fs');
const path = require('path');

// ---------- settings ----------

const PORTS = {
  'Seattle Port': [-122.3393, 47.6026],
  'LA Port': [-118.276, 33.7406],
  'Miami Port': [-80.1794, 25.7781],
  'New York Port': [-74.0445, 40.6681],
  'Rotterdam Port': [4.1, 51.95],
  'Shanghai Port': [121.8, 31.35],
};

const ROUTES = [
  ['Seattle Port', 'LA Port'],
  ['New York Port', 'Rotterdam Port'],
  ['LA Port', 'Shanghai Port'],
  ['Miami Port', 'LA Port'],
];

const SHIP_SPEED_KNOTS = 20; // for the travel-time estimate
const OUT_DIR = __dirname;

// ---------- helpers ----------

const KM_PER_NM = 1.852;
const EARTH_RADIUS_KM = 6371.0088;

// Great-circle distance in nautical miles between two [lng, lat] points.
function haversineNm([lng1, lat1], [lng2, lat2]) {
  const r = Math.PI / 180;
  const dLat = (lat2 - lat1) * r;
  const dLng = (lng2 - lng1) * r;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * r) * Math.cos(lat2 * r) * Math.sin(dLng / 2) ** 2;
  return (2 * EARTH_RADIUS_KM * Math.asin(Math.sqrt(h))) / KM_PER_NM;
}

// One CSV cell: quote it if it contains a comma, quote or line break.
function cell(value) {
  if (value === null || value === undefined) return '';
  const text = typeof value === 'object' ? JSON.stringify(value) : String(value);
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

const row = (values) => values.map(cell).join(',');

function writeCsv(fileName, header, rows) {
  const file = path.join(OUT_DIR, fileName);
  fs.writeFileSync(file, [row(header), ...rows.map(row)].join('\r\n') + '\r\n');
  console.log(`  wrote ${file} (${rows.length} rows)`);
}

const pointFeature = (coordinates) => ({
  type: 'Feature',
  properties: {},
  geometry: { type: 'Point', coordinates },
});

const round = (n, digits = 3) => (Number.isFinite(n) ? Number(n.toFixed(digits)) : n);

// ---------- 1) routes ----------

console.log('Loading searoute-js (the first load can take a while)...');
console.time('load');
const searoute = require('searoute-js');
console.timeEnd('load');

const summaryRows = [];
const waypointRows = [];

ROUTES.forEach(([fromName, toName], index) => {
  const routeId = index + 1;
  const from = PORTS[fromName];
  const to = PORTS[toName];
  console.log(`Route ${routeId}: ${fromName} -> ${toName}`);

  let route;
  try {
    route = searoute(pointFeature(from), pointFeature(to)); // default units: nautical miles
  } catch (err) {
    console.error(`  failed: ${err.message}`);
  }

  const greatCircleNm = haversineNm(from, to);

  if (!route || !route.geometry || !route.geometry.coordinates) {
    console.log('  no route found');
    summaryRows.push([routeId, fromName, toName, '', '', '', '', 0, round(greatCircleNm, 1), '', '', 'no route found']);
    return;
  }

  const coords = route.geometry.coordinates;
  const props = route.properties || {};

  // Waypoints with segment and running distances (great circle between consecutive points).
  let cumulativeNm = 0;
  coords.forEach(([lng, lat], i) => {
    const segmentNm = i === 0 ? 0 : haversineNm(coords[i - 1], coords[i]);
    cumulativeNm += segmentNm;
    waypointRows.push([
      routeId, fromName, toName, i + 1, round(lng, 6), round(lat, 6),
      round(segmentNm), round(cumulativeNm), round(cumulativeNm * KM_PER_NM),
    ]);
  });

  const hours = cumulativeNm / SHIP_SPEED_KNOTS;
  summaryRows.push([
    routeId, fromName, toName,
    round(props.length), props.units ?? '',
    round(props.originSnapDistance), round(props.destinationSnapDistance),
    coords.length,
    round(greatCircleNm, 1),
    round(cumulativeNm / greatCircleNm, 2),
    round(hours, 1),
    `${round(hours / 24, 2)} days at ${SHIP_SPEED_KNOTS} kn`,
  ]);
  console.log(`  ${round(cumulativeNm, 1)} nm by sea vs ${round(greatCircleNm, 1)} nm great circle, ${coords.length} waypoints`);
});

console.log('Writing CSV files:');
writeCsv(
  'routes_summary.csv',
  ['route_id', 'origin', 'destination', 'searoute_length', 'searoute_units', 'origin_snap_distance',
    'destination_snap_distance', 'waypoints', 'great_circle_nm', 'sea_vs_great_circle', 'eta_hours', 'note'],
  summaryRows,
);
writeCsv(
  'route_waypoints.csv',
  ['route_id', 'origin', 'destination', 'seq', 'lng', 'lat', 'segment_nm', 'cumulative_nm', 'cumulative_km'],
  waypointRows,
);

// ---------- 2) optional: the whole shipping-lane network ----------

// Finds the GeoJSON data file(s) shipped inside the searoute-js package, so this
// works whatever the data file is called in the version you installed.
function findNetworkFiles(dir, found = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (entry.name !== 'node_modules') findNetworkFiles(full, found);
    } else if (/\.(geo)?json$/i.test(entry.name) && entry.name !== 'package.json') {
      found.push(full);
    }
  }
  return found;
}

function exportNetwork() {
  const packageDir = path.dirname(require.resolve('searoute-js/package.json'));
  const files = findNetworkFiles(packageDir);
  console.log(`Searching ${packageDir} for network data: ${files.length} JSON file(s)`);

  const file = path.join(OUT_DIR, 'searoute_network.csv');
  const out = fs.openSync(file, 'w');
  fs.writeSync(out, row(['source_file', 'feature_id', 'geometry_type', 'seq', 'lng', 'lat', 'properties']) + '\r\n');

  let features = 0;
  let points = 0;
  for (const jsonFile of files) {
    let geojson;
    try {
      geojson = JSON.parse(fs.readFileSync(jsonFile, 'utf8'));
    } catch {
      continue; // not valid JSON, skip
    }
    if (!geojson || geojson.type !== 'FeatureCollection' || !Array.isArray(geojson.features)) continue;

    const sourceName = path.relative(packageDir, jsonFile);
    geojson.features.forEach((feature, fi) => {
      const geom = feature.geometry;
      if (!geom) return;
      // Flatten Point / LineString / MultiLineString into a list of [lng, lat].
      const lines =
        geom.type === 'Point' ? [[geom.coordinates]]
          : geom.type === 'LineString' ? [geom.coordinates]
            : geom.type === 'MultiLineString' ? geom.coordinates
              : [];
      let seq = 0;
      const featureId = feature.id ?? fi;
      const propsText = feature.properties && Object.keys(feature.properties).length ? feature.properties : '';
      for (const line of lines) {
        for (const [lng, lat] of line) {
          seq += 1;
          points += 1;
          fs.writeSync(out, row([sourceName, featureId, geom.type, seq, lng, lat, seq === 1 ? propsText : '']) + '\r\n');
        }
      }
      features += 1;
    });
  }
  fs.closeSync(out);
  console.log(`  wrote ${file} (${features} features, ${points} points)`);
}

if (process.argv.includes('--network')) exportNetwork();

console.log('Done.');